package io.tornado.api;
import io.tornado.persistence.CoinRepository;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.Test;import java.io.*;import java.math.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class ExcelReportServiceTest{@Test void workbookLabelsSelectedTpAndExactConfiguredPercent()throws Exception{CoinRepository coins=mock(CoinRepository.class);ReportService reports=mock(ReportService.class);when(coins.findAllByActiveTrueOrderBySymbol()).thenReturn(List.of());when(reports.targetPercent(2)).thenReturn(new BigDecimal("0.55"));when(reports.superExcelRows(3,2)).thenReturn(List.of());byte[]bytes=new ExcelReportService(coins,reports).superAnalysis(3,2);try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){var report=book.getSheet("Report");assertThat(report.getRow(1).getCell(1).getStringCellValue()).isEqualTo("TP2");assertThat(report.getRow(1).getCell(2).getStringCellValue()).isEqualTo("0.55%");assertThat(book.getSheet("15 min").getRow(0).getCell(3).getStringCellValue()).isEqualTo("TP2 hit rate");}}}
